// 가송 디자이너 전달 시안. 기존 검토 화면과 스타일을 격리한다.
import {renderFigmaHome,figmaHomeStyles} from './home/figma-home.mjs';
import {categoryArtwork} from './category-artwork.mjs';
const base='/assets/designer-20261013/';
const img=(file,cls='',alt='')=>`<img class="${cls}" src="${base}${file}" alt="${alt}">`;
export const categoryRows=[['한식','중식','일식','양식'],['분식','아시안/세계음식','치킨'],['패스트푸드/도시락','카페/베이커리'],['샐러드/비건','야식/술집/포차'],['의료/건강','헤어/뷰티'],['반려동물/동물병원','부동산/인테리어'],['운동/스포츠/레저','자동차','교육/학원'],['출산/육아','문구/완구/취미','액세서리/잡화'],['전문서비스업','생활서비스']];
const selected=['치킨','패스트푸드/도시락','헤어/뷰티','운동/스포츠/레저'];
const icon=categoryArtwork;
function nav(myland=false){return `<nav class="bottom-nav" aria-label="하단 메뉴">${[['홈',myland?'96c0f.svg':'b6889.svg'],['마이랜드',myland?'ce3a9.svg':'e987b.svg'],['내 바코드','77fa8.svg'],['오지파크','c10fd.svg'],['내 정보','eeba5.svg']].map(([label,file],i)=>`<div class="nav-item ${i===(myland?1:0)?'active':''} ${i===2?'barcode':''}"><span>${img(file)}</span><small>${label}</small></div>`).join('')}</nav>`;}
function home(background=false){return `<div class="screen home"${background?' inert aria-hidden="true"':''}>${renderFigmaHome()}</div>`;}
function categories(after,full){return `<div class="screen category ${full?'full':''}">${full?'':home(true)+'<div class="dim"></div>'}<section class="filter-panel">${full?'':'<div class="handle"></div>'}<header>${full?img('86134.svg','back'):''}<b>카테고리 전체보기</b><strong data-selection-count>${after?'4':''}</strong></header><div class="category-content" role="region" tabindex="0" aria-label="업종 목록">${categoryRows.map((row,index)=>`${index===0?'<h3>음식점</h3>':index===4?'<h3 class="convenience">생활편의</h3>':''}<div class="category-row">${row.map(name=>`<button class="category-chip" data-category="${name}" aria-pressed="${after&&selected.includes(name)}"><span>${icon(name)}</span>${name}</button>`).join('')}</div>`).join('')}</div><footer><button data-reset>초기화</button><button class="fill" data-browse>${after?'927':'14,367'}개 둘러보기</button></footer></section></div>`;}
const opinions=`<div class="designer-notes" role="note"><h3>디자이너 의견</h3><p>출석은 스크롤을 줄일 목적으로 1주 단위로 하는 건 어떨까요? <small>구성 제안</small></p><p>티켓 아이콘 필요! <small>추가 제작 필요</small></p><p>미션마다 아이콘 필요! <small>추가 제작 필요</small></p></div>`;
function myland(version){return `<div class="screen myland v${version}">${img('fc001.png','bear')}<h1>마이랜드</h1><section class="attendance card"><div class="attendance-top"><div class="attendance-heading"><b>출석하고 티켓받기</b><span>누적 출석 <strong>3일차</strong></span></div><div class="week">${['일','월','화','수','목','금','토'].map((day,i)=>`<div>${i===0||i===4?img('46540.svg','attendance-icon'):i===3||i===6?img(i===3?'abff5.svg':'2d5f6.svg','ticket-day'):'<span class="empty-day"></span>'}<small>${day}</small></div>`).join('')}</div><button class="fill attendance-button">출석하기</button></div><div class="stats"><div><small>사용 가능 M</small><b>15,000 M</b></div><div><small>티켓</small><b>${img('10e0b.svg')}71</b></div><div><small>공유 적립 M <em>${img('1a522.svg')}58</em></small><b>1,250</b></div></div></section><div class="games">${[['룰렛','57','933fc.png'],['퍼즐','14','99ca4.png']].map(([label,count,file])=>`<section class="game card"><b>${label}</b><small>${img('a3be4.svg')}${count}</small>${img(file,'game-art')}</section>`).join('')}</div><section class="missions card"><header><b>이번주 미션</b><strong>2<span>/4</span></strong></header><div class="progress"><span></span></div><div class="mission-list">${[['마이랜드 방문하기','','+10M'],['룰렛 2회 돌리기','1/2','방문하기'],['회원점 1곳에서 적립하기','3티켓','방문하기'],['공유인 1명 초대하기','','공유하기']].map(([label,extra,action],i)=>`<div class="mission"><span class="mission-icon">${img('ee751.svg')}${img('b2e4e.svg','tiny-check')}</span><span class="mission-label">${label}${extra?`<em>${extra}</em>`:''}</span><button class="${i?'fill':''}">${action}</button></div>`).join('')}</div></section>${nav(true)}</div>`;}
export function renderDesignerScreen(name){return name==='home'?home():name.startsWith('myland')?myland(name.endsWith('2')?2:1):categories(name!=='category-before',name==='category-full');}
export function designerStyles(name){return [...(name.startsWith('myland')?[]:figmaHomeStyles),'/v2/designer-20261013.css',...(name.startsWith('myland')?[]:['/v2/home/figma-home.css','/v2/components/figma-navigation.css'])];}
function frame(name,label){return `<figure class="designer-figure"><figcaption>${label}</figcaption><div class="designer-host" data-designer-screen="${name}"><template>${designerStyles(name).map(href=>`<link rel="stylesheet" href="${href}">`).join('')}${renderDesignerScreen(name)}</template></div></figure>`;}
const layout='<style>.designer-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,390px),1fr));gap:32px;align-items:start}.designer-figure{margin:0;max-width:390px;min-width:0}.designer-figure figcaption{font-weight:700;margin:0 0 16px}.designer-host{width:100%;overflow:hidden}.designer-notes{max-width:850px;margin-top:28px;line-height:1.7}.designer-notes small{color:#b9b6f5;margin-left:12px}</style>';
export function renderCategoryDesignerReview(){return `<section id="category-design" data-review-screen>${layout}<h2>카테고리 시안</h2><div class="designer-grid">${frame('home','홈 화면')}${frame('category-before','카테고리 선택 전')}${frame('category-after','카테고리 선택 후')}${frame('category-full','전체 화면형 비교안')}</div><div class="designer-notes" role="note"><h3>디자이너 의견</h3><p>필터 종류가 추후 늘어날 예정이라면, 바텀시트 대신 팝업 형태의 전체 화면형으로 적용해주세요.</p><p>홈에서도 필터 안에서도 전체 아이콘을 사용할 필요가 없습니다. 홈에서 어떤 필터도 선택하지 않은 상태가 전체보기입니다.</p><p>필터 선택 시 검색으로 넘어가며, 필터에서는 초기화 버튼이 더 간편하므로 전체보기가 필요하지 않습니다.</p></div></section>`;}
export function renderMyLandDesignerReview(){return `<section id="myland-design" data-review-screen>${layout}<h2>마이랜드 시안</h2><div class="designer-grid">${frame('myland-v1','마이랜드 v1')}${frame('myland-v2','마이랜드 v2')}</div>${opinions}</section>`;}
export function setupCategoryControls(shadow){
 const panel=shadow.querySelector('.filter-panel');if(!panel)return;
 const update=()=>{const chosen=[...panel.querySelectorAll('[data-category][aria-pressed="true"]')].map(el=>el.dataset.category);const count=chosen.length;panel.querySelector('[data-selection-count]').textContent=count||'';panel.querySelector('[data-browse]').textContent=count===0?'14,367개 둘러보기':count===4&&selected.every(name=>chosen.includes(name))?'927개 둘러보기':'선택한 업종 둘러보기';};
 shadow.addEventListener('click',event=>{const chip=event.target.closest('.filter-panel [data-category]');if(chip){chip.setAttribute('aria-pressed',String(chip.getAttribute('aria-pressed')!=='true'));update();}if(event.target.closest('[data-reset]')){panel.querySelectorAll('[data-category]').forEach(el=>el.setAttribute('aria-pressed','false'));update();}});
}
export function setupDesignerReview(root){for(const host of root.querySelectorAll('[data-designer-screen]')){const template=host.querySelector('template'),shadow=host.attachShadow({mode:'open'});shadow.append(template.content.cloneNode(true));template.remove();const screen=shadow.querySelector('.screen');const resize=()=>{const scale=Math.min(1,host.clientWidth/390);screen.style.zoom=scale;host.style.height=(host.dataset.designerScreen.startsWith('myland')?879:846)*scale+'px';};new ResizeObserver(resize).observe(host);resize();shadow.querySelector('form')?.addEventListener('submit',event=>event.preventDefault());setupCategoryControls(shadow);}}
